do $$ begin
  if not exists (select from pg_roles where rolname = 'pgy_fx_owner') then create role pgy_fx_owner; end if;
  if not exists (select from pg_roles where rolname = 'pgy_fx_reader') then create role pgy_fx_reader; end if;
end $$;
create schema s4 authorization pgy_fx_owner;
grant usage on schema s4 to pgy_fx_reader;
create type s4.kind as enum ('a', 'b');
alter type s4.kind owner to pgy_fx_owner;
grant usage on type s4.kind to pgy_fx_reader;
create domain s4.pos as int check (value > 0);
alter domain s4.pos owner to pgy_fx_owner;
create table s4.t (id int primary key, k s4.kind, n s4.pos, secret text);
alter table s4.t owner to pgy_fx_owner;
grant select (id, k), update (k) on s4.t to pgy_fx_reader;
grant insert on s4.t to pgy_fx_reader with grant option;
create sequence s4.seq;
alter sequence s4.seq owner to pgy_fx_owner;
grant usage, select on sequence s4.seq to pgy_fx_reader;
create view s4.v as select id from s4.t;
alter view s4.v owner to pgy_fx_owner;
grant select on s4.v to pgy_fx_reader;
create materialized view s4.mv as select 1 as x;
alter materialized view s4.mv owner to pgy_fx_owner;
create function s4.f() returns int language sql as 'select 1';
alter function s4.f() owner to pgy_fx_owner;
revoke execute on function s4.f() from public;
grant execute on function s4.f() to pgy_fx_reader;
create procedure s4.p() language sql as 'select 1';
alter procedure s4.p() owner to pgy_fx_owner;
alter default privileges for role pgy_fx_owner in schema s4 grant select on tables to pgy_fx_reader;
alter default privileges for role pgy_fx_owner revoke execute on functions from public;
